type TicketDisplayDateFormat = 'localized' | 'iso';

const formatIsoDate = (
  date: Date,
  timeZoneOptions: Intl.DateTimeFormatOptions
): string => {
  const dateParts = new Intl.DateTimeFormat('en-US', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    ...timeZoneOptions,
  }).formatToParts(date);
  const year = dateParts.find((part) => part.type === 'year')?.value;
  const month = dateParts.find((part) => part.type === 'month')?.value;
  const day = dateParts.find((part) => part.type === 'day')?.value;

  return year && month && day ? `${year}-${month}-${day}` : '--';
};

const formatLocalizedDate = (
  date: Date,
  language: string,
  timeZoneOptions: Intl.DateTimeFormatOptions
): string => {
  const locale = language || 'en';
  const formattedDate = new Intl.DateTimeFormat(locale, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    ...timeZoneOptions,
  }).format(date);

  if (locale === 'zh-Hant' || locale === 'zh-Hans') {
    return formattedDate;
  }

  const parts = new Intl.DateTimeFormat('en-US', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    ...timeZoneOptions,
  }).formatToParts(date);
  const day = parts.find((part) => part.type === 'day')?.value;
  const month = parts.find((part) => part.type === 'month')?.value;
  const year = parts.find((part) => part.type === 'year')?.value;

  return day && month && year ? `${day} ${month}. ${year}` : formattedDate;
};

export const formatTicketDisplayDateTime = (
  isoDateTime: string | undefined,
  language: string,
  timeZone?: string,
  dateFormat: TicketDisplayDateFormat = 'localized'
): TicketDisplayDateTime => {
  const invalid: TicketDisplayDateTime = { date: '--', time: '--' };

  if (!isoDateTime) {
    return invalid;
  }

  const date = new Date(isoDateTime);

  if (Number.isNaN(date.getTime())) {
    return invalid;
  }

  const timeZoneOptions: Intl.DateTimeFormatOptions = timeZone
    ? { timeZone }
    : {};
  const displayDate =
    dateFormat === 'iso'
      ? formatIsoDate(date, timeZoneOptions)
      : formatLocalizedDate(date, language, timeZoneOptions);

  const formattedTime = new Intl.DateTimeFormat('en-GB', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
    ...timeZoneOptions,
  }).format(date);

  return {
    date: displayDate,
    time: formattedTime,
  };
};

export const getTicketDisplayDateTime = (
  ticket: Ticket,
  language: string,
  timeZone?: string,
  dateFormat: TicketDisplayDateFormat = 'localized'
): TicketDisplayDateTime =>
  formatTicketDisplayDateTime(
    getTicketDisplayDateTimeSource(ticket),
    language,
    timeZone,
    dateFormat
  );

